/**
 * Local model management (T13, doc 03 §6).
 *
 * - external mode: use an Ollama already running (never reconfigure it);
 * - managed mode: start our own loopback process with an explicit models dir;
 * - GGUF import: a Modelfile generated by the app (never a user-supplied
 *   file), fixed arguments, no shell.
 *
 * Nothing here downloads large models or touches Windows environment vars.
 */

import { spawn, type ChildProcess } from 'node:child_process';
import { existsSync, mkdtempSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

export interface ManagedOllamaOptions {
  executable: string;
  modelsDir: string | null;
  host?: string;
  port?: number;
  spawnImpl?: typeof spawn;
}

export class ModelManagerError extends Error {
  readonly code: string;

  constructor(code: string, message: string) {
    super(message);
    this.name = 'ModelManagerError';
    this.code = code;
  }
}

export class ManagedOllama {
  private child: ChildProcess | null = null;
  private readonly spawnImpl: typeof spawn;

  constructor(private readonly options: ManagedOllamaOptions) {
    this.spawnImpl = options.spawnImpl ?? spawn;
  }

  get running(): boolean {
    return this.child !== null;
  }

  validateExecutable(): string {
    const path = this.options.executable;
    if (!path || !existsSync(path)) {
      throw new ModelManagerError('OLLAMA_MISSING', 'O executável do Ollama não existe.');
    }
    if (!statSync(path).isFile()) {
      throw new ModelManagerError('OLLAMA_MISSING', 'O caminho do Ollama não é um arquivo.');
    }
    if (this.options.modelsDir && !existsSync(this.options.modelsDir)) {
      throw new ModelManagerError('MODELS_DIR_MISSING', 'A pasta de modelos não existe.');
    }
    return path;
  }

  async start(): Promise<{ host: string; port: number }> {
    const executable = this.validateExecutable();
    const host = this.options.host ?? '127.0.0.1';
    const port = this.options.port ?? 0; // let the runtime pick when 0
    const env: NodeJS.ProcessEnv = { ...process.env, OLLAMA_HOST: `${host}:${port}` };
    if (this.options.modelsDir) {
      // Applied ONLY to the process we own — never to Windows globally.
      env.OLLAMA_MODELS = this.options.modelsDir;
    }
    const child = this.spawnImpl(executable, ['serve'], {
      env,
      shell: false,
      windowsHide: true,
      // Nobody reads the output; an unread pipe could fill and stall the server.
      stdio: 'ignore',
    });
    this.child = child;
    const forget = () => {
      if (this.child === child) this.child = null;
    };
    child.on('exit', forget);
    // A spawn failure is reported as an 'error' event; without a listener it
    // would take the whole main process down.
    child.on('error', forget);
    return { host, port };
  }

  async stop(timeoutMs = 5000): Promise<void> {
    const child = this.child;
    if (!child) return;
    await new Promise<void>((resolve) => {
      const timer = setTimeout(() => {
        try {
          child.kill('SIGKILL');
        } catch {
          /* gone */
        }
        resolve();
      }, timeoutMs);
      child.once('exit', () => {
        clearTimeout(timer);
        resolve();
      });
      try {
        child.kill('SIGTERM');
      } catch {
        clearTimeout(timer);
        resolve();
      }
    });
    this.child = null;
  }
}

export interface GgufImportPlan {
  modelfile: string;
  tag: string;
  cleanup: () => void;
}

/**
 * Builds the temporary Modelfile for a GGUF import. The FROM line points at
 * the selected file; nothing from the user is executed as a directive.
 */
export function planGgufImport(ggufPath: string, tag: string): GgufImportPlan {
  if (!existsSync(ggufPath) || !ggufPath.toLowerCase().endsWith('.gguf')) {
    throw new ModelManagerError('GGUF_INVALID', 'Selecione um arquivo .gguf existente.');
  }
  if (!/^[a-zA-Z0-9][a-zA-Z0-9._\-/:]{0,79}$/.test(tag)) {
    throw new ModelManagerError(
      'TAG_INVALID',
      'A tag local deve ter 1–80 caracteres alfanuméricos (., _, -, /, :).',
    );
  }
  // A newline or quote in the path would let the path inject Modelfile
  // directives: the only accepted content is one FROM line.
  if (/[\r\n\0"]/.test(ggufPath)) {
    throw new ModelManagerError('GGUF_INVALID', 'O caminho do arquivo contém caracteres não permitidos.');
  }
  const dir = mkdtempSync(join(tmpdir(), 'converter-modelfile-'));
  const modelfile = join(dir, 'Modelfile');
  // Paths with spaces are quoted; the file is generated by us, not the user.
  writeFileSync(modelfile, `FROM "${ggufPath}"\n`, 'utf8');
  return {
    modelfile,
    tag,
    cleanup: () => {
      try {
        rmSync(dir, { recursive: true, force: true });
      } catch {
        /* best effort */
      }
    },
  };
}

export function ollamaCreateArgs(plan: GgufImportPlan): string[] {
  // Fixed argument list: `ollama create <tag> -f <generated Modelfile>`.
  return ['create', plan.tag, '-f', plan.modelfile];
}

const ANSI_PATTERN = /\x1b\[[0-9;?]*[A-Za-z]/g;
const IMPORT_TIMEOUT_MS = 30 * 60 * 1000;
const IMPORT_OUTPUT_CHARS = 8 * 1024;

export interface GgufImportOptions {
  executable: string;
  /** Loopback host and port of the managed Ollama server the CLI talks to. */
  host: string;
  port: number;
  plan: GgufImportPlan;
  onProgress?: (line: string) => void;
  spawnImpl?: typeof spawn;
  timeoutMs?: number;
}

export interface GgufImportResult {
  tag: string;
  exitCode: number;
}

/**
 * Runs `ollama create <tag> -f <generated Modelfile>` with fixed arguments and
 * no shell. OLLAMA_HOST is set for this child only; OLLAMA_MODELS is not set
 * here (the managed server owns the models directory). Progress lines are
 * forwarded without ANSI control codes; the output kept for errors is bounded.
 */
export async function runGgufImport(options: GgufImportOptions): Promise<GgufImportResult> {
  const spawnImpl = options.spawnImpl ?? spawn;
  const args = ollamaCreateArgs(options.plan);
  const env: NodeJS.ProcessEnv = { ...process.env, OLLAMA_HOST: `${options.host}:${options.port}` };
  const child = spawnImpl(options.executable, args, {
    env,
    shell: false,
    windowsHide: true,
    stdio: ['ignore', 'pipe', 'pipe'],
  }) as ChildProcess;

  let tail = '';
  let pending = '';
  const onChunk = (chunk: Buffer | string) => {
    pending += chunk.toString();
    const lines = pending.split(/\r?\n|\r/);
    pending = lines.pop() ?? '';
    for (const raw of lines) {
      const line = raw.replace(ANSI_PATTERN, '').trim();
      if (!line) continue;
      tail = `${tail}\n${line}`.slice(-IMPORT_OUTPUT_CHARS);
      options.onProgress?.(line);
    }
  };
  child.stdout?.on('data', onChunk);
  child.stderr?.on('data', onChunk);

  const timeoutMs = options.timeoutMs ?? IMPORT_TIMEOUT_MS;
  const exitCode = await new Promise<number>((resolve, reject) => {
    const timer = setTimeout(() => {
      try {
        child.kill('SIGKILL');
      } catch {
        /* already gone */
      }
      reject(new ModelManagerError('GGUF_IMPORT_TIMEOUT', 'A importação do GGUF excedeu o tempo limite.'));
    }, timeoutMs);
    child.once('error', (error) => {
      clearTimeout(timer);
      reject(new ModelManagerError('GGUF_IMPORT_SPAWN_FAILED', `Falha ao executar o Ollama: ${error.message}`));
    });
    child.once('exit', (code) => {
      clearTimeout(timer);
      resolve(code ?? -1);
    });
  });

  if (exitCode !== 0) {
    throw new ModelManagerError(
      'GGUF_IMPORT_FAILED',
      `ollama create terminou com código ${exitCode}. ${tail.slice(-800)}`.trim(),
    );
  }
  return { tag: options.plan.tag, exitCode };
}

/** Digest of a tag, used in checkpoint fingerprints. */
export async function tagDigest(
  baseUrl: string,
  tag: string,
  fetchImpl: typeof fetch = fetch,
): Promise<string | null> {
  try {
    const response = await fetchImpl(`${baseUrl}/api/tags`);
    if (!response.ok) return null;
    const payload = (await response.json()) as { models?: Array<{ name?: string; digest?: string }> };
    const match = (payload.models ?? []).find((item) => item.name === tag);
    return match?.digest ?? null;
  } catch {
    return null;
  }
}
